{
  "name": "node-shop",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  },
  "dependencies": {
    "express": "^5.1.0",
    "pg": "^8.16.0"
  },
  "devDependencies": {
    "prettier": "^3.6.0"
  }
}

import express from 'express'
import pg from 'pg'

// pg reads PGHOST, PGUSER, PGPASSWORD and PGDATABASE from the environment.
const db = new pg.Client()
await db.connect()
console.log('Connected to', process.env.PGHOST)

const app = express()
app.get('/', async (req, res) => {
  const { rows } = await db.query('SELECT now() AS time')
  res.json({ message: 'Hello from node-shop', databaseTime: rows[0].time })
})
const server = app.listen(3000, '0.0.0.0', () => console.log('Listening on port 3000'))

process.on('SIGTERM', () => {
  console.log('Stopping')
  server.close(() => db.end().then(() => process.exit(0)))
})
